  EventHandler,
  EventHandlerRequest,
  HTTPHandler,
  H3Event,
  RouteDefinition,
  RouteRules,
  TypedHeaders,
  WebSocketResponse,
} from "../../src/index.ts";
import { H3 } from "../../src/index.ts";
import { describe, it, expectTypeOf } from "vitest";
import {
  defineHandler,
  getQuery,
  readBody,
  readValidatedBody,
  getValidatedQuery,
  defineValidatedHandler,
