    it("accepts a handler with a concrete request type in an untyped slot", () => {
      expectTypeOf<EventHandler<{ body: { id: string } }>>().toExtend<HTTPHandler>();
    });
  });

  describe("handler passthrough", () => {
    const handler = defineValidatedHandler({
      validate: { body: z.object({ title: z.string() }) },
      handler: () => "ok",
    });

    it("keeps the request type through toEventHandler", () => {
      const normalized = toEventHandler(handler)!;
      expectTypeOf<ReqOf<typeof normalized>["body"]>().toEqualTypeOf<{ title: string }>();
    });

    it("keeps the request type through withBase", () => {
      const based = withBase("/api", handler);
      expectTypeOf<ReqOf<typeof based>["body"]>().toEqualTypeOf<{ title: string }>();
    });

    it("keeps the request type through defineLazyEventHandler", () => {
      const lazy = defineLazyEventHandler(() => handler);
      expectTypeOf<ReqOf<typeof lazy>["body"]>().toEqualTypeOf<{ title: string }>();
    });

    it("does not leak any for a plain HTTPHandler", () => {
      const plain = handler as HTTPHandler;

      const normalized = toEventHandler(plain)!;
      expectTypeOf<ReqOf<typeof normalized>>().not.toBeAny();
      expectTypeOf<ReqOf<typeof normalized>>().toEqualTypeOf<EventHandlerRequest>();

      const based = withBase("/api", plain);
      expectTypeOf<ReqOf<typeof based>>().not.toBeAny();
      expectTypeOf<ReqOf<typeof based>>().toEqualTypeOf<EventHandlerRequest>();

      const lazy = defineLazyEventHandler(() => plain);
      expectTypeOf<ReqOf<typeof lazy>>().not.toBeAny();
      expectTypeOf<ReqOf<typeof lazy>>().toEqualTypeOf<EventHandlerRequest>();
    });

    it("uses the default request type for an H3 instance", () => {
      const normalized = toEventHandler(new H3())!;
      expectTypeOf<ReqOf<typeof normalized>>().not.toBeAny();
      expectTypeOf<ReqOf<typeof normalized>>().toEqualTypeOf<EventHandlerRequest>();
    });
  });

  describe("getQuery", () => {
    it("untyped", () => {
      defineHandler((event) => {
        const query = getQuery(event);
        expectTypeOf(query).not.toBeAny();
        expectTypeOf(query).toEqualTypeOf<Partial<Record<string, string | string[]>>>();
      });
    });

    it("typed via generic", () => {
      defineHandler((event) => {
        const query = getQuery<{ id: string }>(event);
        expectTypeOf(query).not.toBeAny();
        expectTypeOf(query).toEqualTypeOf<{ id: string }>();
      });
    });

    it("typed via validator", () => {
      defineHandler(async (event) => {
        const validator = (body: unknown) => body as { id: string };
        const body = await getValidatedQuery(event, validator);
        expectTypeOf(body).not.toBeAny();
        expectTypeOf(body).toEqualTypeOf<{ id: string }>();
      });
    });

    it("typed via zod schema", () => {
      defineHandler(async (event) => {
        const query = await getValidatedQuery(
          event,
          z.object({
            search: z.string().optional(),
          }),
        );
        expectTypeOf(query).not.toBeAny();
        expectTypeOf(query).toEqualTypeOf<{ search?: string | undefined }>();
      });
    });

    it("typed via zod schema in defineEventHandler object", () => {
      defineEventHandler({
        async handler(event) {
          const query = await getValidatedQuery(
            event,
            z.object({
              search: z.string().optional(),
            }),
          );
          expectTypeOf(query).not.toBeAny();
          expectTypeOf(query).toEqualTypeOf<{ search?: string | undefined }>();
        },
      });
    });

    it("typed via event handler", () => {
      defineHandler<{ query: { id: string } }>((event) => {
        const query = getQuery(event);
        expectTypeOf(query).not.toBeAny();
        expectTypeOf(query).toEqualTypeOf<{ id: string }>();
      });
    });
  });

  describe("defineWebSocketHandler", () => {
    it("exposes crossws on the returned response type without a cast", () => {
      // https://github.com/h3js/h3/issues/1258
      // Given a WebSocket handler defined via defineWebSocketHandler
      const wsHandler = defineWebSocketHandler({ message: () => {} });
      // When the handler is invoked directly (as crossws adapters do)
      const res = wsHandler({} as H3Event);
      // Then `crossws` must be visible on the returned type, with no `as any` cast
      expectTypeOf(res).toHaveProperty("crossws");
    });

    it("still types the http fallback handler's return value", () => {
      // Given a WebSocket handler with an http fallback returning a string
      const wsHandler = defineWebSocketHandler({ message: () => {} }, () => "hello");
      const res = wsHandler({} as H3Event);
      // Then the returned type is the union of the WebSocket response
      // (with `crossws` visible) and the http handler's return type —
      // neither branch is widened away.
      expectTypeOf(res).toExtend<string | (Response & { crossws?: unknown })>();
      expectTypeOf(res).not.toBeUnknown();
    });

    it("types an async hooks factory's return value without a cast", async () => {
      // Given a WebSocket handler defined with an async hooks factory
      const wsHandler = defineWebSocketHandler(async (_event) => {
        await Promise.resolve();
        return { message: () => {} };
      });
      // When the handler is invoked directly (as crossws adapters do)
      const res = wsHandler({} as H3Event);
      // Then the return type must itself be the union of the sync response
      // and a Promise of it, not just `WebSocketResponse`. Otherwise
      // await-ing a sync-typed value would be a no-op and this assertion
      // would pass regardless of whether the factory was actually awaited.
      expectTypeOf(res).toEqualTypeOf<WebSocketResponse | Promise<WebSocketResponse>>();
      // And the resolved value still exposes `crossws` with no cast.
      const awaited = await res;
      expectTypeOf(awaited).toHaveProperty("crossws");
    });
  });
});

// Route rules are declared empty by h3 and filled in by modules
// (`h3-rules`, Nitro, ...) through declaration merging.
declare module "../../src/index.ts" {
  interface RouteRules {
    swr?: number | boolean;
  }
}

describe("routeRules", () => {
  it("augmented keys merge into the interface used by the event context", () => {
    defineHandler((event) => {
      // The augmentation reaches `RouteRules` through h3's re-export, so the
      // key keeps its declared type rather than widening to `any`/`unknown`.
      expectTypeOf(event.context.routeRules?.swr).toEqualTypeOf<number | boolean | undefined>();
    });
  });

  it("stays closed for keys nobody declared", () => {
    defineHandler((event) => {
      // @ts-expect-error unknown rule keys are a compile error until augmented
      event.context.routeRules?.notDeclaredAnywhere;
    });
  });

  it("exposes matched rules as readonly", () => {
    defineHandler((event) => {
      // Matchers are typically memoized, so a matched object can be shared
      // between requests. Rules are readonly even though augmenters declare
      // their keys as mutable.
      // @ts-expect-error matched rules must not be mutated in place
      event.context.routeRules.swr = 60;
    });
  });

  it("allows replacing the whole object", () => {
    defineHandler((event) => {
      // How rule modules attach matched rules (see Nitro's generated middleware).
      event.context.routeRules = {} as RouteRules;
    });
  });
});

describe("deprecated v1 signatures", () => {
  // The v1 signature took a headers record; the implementation still iterates one
  // with `Object.entries`, so the declared `string` makes the export uncallable.
  it("appendResponseHeaders takes a headers record", () => {
    expectTypeOf(appendResponseHeaders).toBeCallableWith({} as H3Event, { "x-foo": "bar" });
    expectTypeOf(appendHeaders).toBeCallableWith({} as H3Event, { "x-foo": "bar" });
  });

  // v1 defaulted to 302 and the delegated `redirect()` still does, so the status is optional.
  it("sendRedirect leaves the status code optional", () => {
    expectTypeOf(sendRedirect).toBeCallableWith({} as H3Event, "/target");
  });
});

describe("basicAuth context", () => {
  // `requireBasicAuth` has a single write site and it always assigns `username`
  // (a `slice` result) and `realm` (`opts.realm ?? "auth"`) as strings, so
  // reading them back must not require a redundant `undefined` check.
  // `password` stays optional so it can be dropped from the context later
  // without a breaking type change.
  it("exposes username and realm as strings once set", () => {
    defineHandler(async (event) => {
      await requireBasicAuth(event, { password: "test" });
      const auth = event.context.basicAuth!;
      expectTypeOf(auth.username).toEqualTypeOf<string>();
      expectTypeOf(auth.password).toEqualTypeOf<string | undefined>();
      expectTypeOf(auth.realm).toEqualTypeOf<string>();
    });
  });

  // The property itself stays optional: it is absent until a request authenticates.
  it("stays optional until a request is authenticated", () => {
    defineHandler((event) => {
      expectTypeOf(event.context.basicAuth).toEqualTypeOf<
        { username: string; password?: string; realm: string } | undefined
      >();
    });
  });
});

import { H3, HTTPError, kNotFound } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

const PROBLEM = "application/problem+json";

describeMatrix(
  "problem details",
  (t, { it, expect, describe }) => {
    describe("RF-01 content-type", () => {
      it("HTTPError", async () => {
        t.app.get("/", () => {
          throw new HTTPError({ status: 400 });
        });
        const res = await t.fetch("/");
        expect(res.status).toBe(400);
        expect(res.headers.get("content-type")).toBe(PROBLEM);
      });

      it("unhandled error", async () => {
        t.app.get("/", () => {
          throw new Error("boom");
        });
        const res = await t.fetch("/");
        t.errors = [];
        expect(res.status).toBe(500);
        expect(res.headers.get("content-type")).toBe(PROBLEM);
      });

      it("kNotFound", async () => {
        t.app.get("/", () => kNotFound);
        const res = await t.fetch("/");
        expect(res.status).toBe(404);
        expect(res.headers.get("content-type")).toBe(PROBLEM);
      });
    });

    describe("RF-02 standard members", () => {
      it("maps type, title, status, detail", async () => {
        t.app.get("/", () => {
          throw new HTTPError({
            status: 404,
            statusText: "Not Found",
            message: "Usuário 42 não existe",
          });
        });
        const res = await t.fetch("/");
        expect(await res.text()).toBe(
          '{"status":404,"statusText":"Not Found","message":"Usuário 42 não existe","type":"about:blank","title":"Not Found","detail":"Usuário 42 não existe"}',
        );
      });

      it("falls back to the standard phrase for title", async () => {
        t.app.get("/", () => {
          throw new HTTPError({ status: 409 });
        });
        const body = await (await t.fetch("/")).json();
        expect(body.title).toBe("Conflict");
      });

      it("omits title for statuses without a phrase", async () => {
        t.app.get("/", () => {
          throw new HTTPError({ status: 299 });
        });
        const body = await (await t.fetch("/")).json();
        expect(body).not.toHaveProperty("title");
      });
    });

    describe("RF-03 type and instance fields", () => {
      const input = { type: "https://example.com/probs/x", instance: "/pedidos/7" };

      it("new HTTPError(details)", () => {
        const error = new HTTPError({ status: 409, ...input });
        expect(error.type).toBe(input.type);
        expect(error.instance).toBe(input.instance);
      });

      it("new HTTPError(message, details)", () => {
        const error = new HTTPError("msg", { status: 409, ...input });
        expect(error.type).toBe(input.type);
        expect(error.instance).toBe(input.instance);
      });

      it("HTTPError.status()", () => {
        const error = HTTPError.status(409, "Conflict", input);
        expect(error.type).toBe(input.type);
        expect(error.instance).toBe(input.instance);
      });

      it("defaults to undefined and ignores non-strings", () => {
        const empty = new HTTPError({ status: 409 });
        expect(empty.type).toBeUndefined();
        expect(empty.instance).toBeUndefined();
        const bad = new HTTPError({ status: 409, type: 1, instance: {} } as any);
        expect(bad.type).toBeUndefined();
        expect(bad.instance).toBeUndefined();
      });
    });

    describe("RF-04 type and instance in response", () => {
      it("uses given values", async () => {
        t.app.get("/", () => {
          throw new HTTPError({
            status: 409,
            type: "https://example.com/probs/conflito",
            instance: "/pedidos/7",
          });
        });
        const body = await (await t.fetch("/")).json();
        expect(body.type).toBe("https://example.com/probs/conflito");
        expect(body.instance).toBe("/pedidos/7");
      });

      it("omits instance when absent", async () => {
        t.app.get("/", () => {
          throw new HTTPError({ status: 409 });
        });
        const body = await (await t.fetch("/")).json();
        expect(body.type).toBe("about:blank");
        expect(body).not.toHaveProperty("instance");
      });
    });

    describe("RF-05 extensions", () => {
      it("keeps extensions but standard members win", async () => {
        t.app.get("/", () => {
          throw new HTTPError({
            status: 422,
            data: { campo: "x" },
            body: { code: "E_PAGAMENTO", status: 999, type: "x", title: "y" },
          });
        });
        const res = await t.fetch("/");
        const body = await res.json();
        expect(res.status).toBe(422);
        expect(body.code).toBe("E_PAGAMENTO");
        expect(body.data).toEqual({ campo: "x" });
        expect(body.status).toBe(422);
        expect(body.type).toBe("about:blank");
        expect(body.title).toBe("Unprocessable Content");
      });
    });

    describe("RF-06 legacy fields", () => {
      it("keeps legacy and new members", async () => {
        t.app.get("/", () => {
          throw new HTTPError({ status: 400, statusText: "Bad Request", message: "inválido" });
        });
        expect(await (await t.fetch("/")).json()).toMatchObject({
          status: 400,
          statusText: "Bad Request",
          message: "inválido",
          type: "about:blank",
          title: "Bad Request",
          detail: "inválido",
        });
      });

      it("toJSON() keys", () => {
        const json = new HTTPError({ status: 400, statusText: "Bad Request", message: "x" }).toJSON();
        expect(JSON.parse(JSON.stringify(json))).toEqual({
          status: 400,
          statusText: "Bad Request",
          message: "x",
          type: "about:blank",
          title: "Bad Request",
          detail: "x",
        });
        expect(Object.keys(json)).toEqual(
          expect.arrayContaining(["status", "statusText", "unhandled", "message", "data"]),
        );
      });
    });

    describe("RF-07 unhandled errors", () => {
      it("does not leak internals", async () => {
        t.app.config.debug = false;
        t.app.get("/", () => {
          throw new Error("segredo interno");
        });
        const res = await t.fetch("/");
        t.errors = [];
        const text = await res.text();
        expect(res.status).toBe(500);
        expect(res.headers.get("content-type")).toBe(PROBLEM);
        expect(text).not.toContain("segredo interno");
        expect(JSON.parse(text)).not.toHaveProperty("stack");
      });

      it("ignores type and instance from library errors", async () => {
        t.app.config.debug = false;
        t.app.get("/", () => {
          throw Object.assign(new Error("too large"), {
            type: "entity.too.large",
            instance: "/internal",
          });
        });
        const body = await (await t.fetch("/")).json();
        t.errors = [];
        expect(body.type).toBe("about:blank");
        expect(body).not.toHaveProperty("instance");
      });

      it("hides everything on an unhandled HTTPError", () => {
        const json = new HTTPError({
          status: 500,
          unhandled: true,
          type: "https://x/y",
          instance: "/z",
          message: "secret",
          data: { a: 1 },
          body: { b: 2 },
        }).toJSON();
        expect(JSON.parse(JSON.stringify(json))).toEqual({
          status: 500,
          message: "HTTPError",
          unhandled: true,
