    expectTypeOf(appendHeaders).toBeCallableWith({} as H3Event, { "x-foo": "bar" });
  });

  // v1 defaulted to 302 and the delegated `redirect()` still does, so the status is optional.
  it("sendRedirect leaves the status code optional", () => {
    expectTypeOf(sendRedirect).toBeCallableWith({} as H3Event, "/target");
  });
});

describe("basicAuth context", () => {
  // `requireBasicAuth` has a single write site and it always assigns `username`
  // (a `slice` result) and `realm` (`opts.realm ?? "auth"`) as strings, so
  // reading them back must not require a redundant `undefined` check.
  // `password` stays optional so it can be dropped from the context later
  // without a breaking type change.
  it("exposes username and realm as strings once set", () => {
    defineHandler(async (event) => {
      await requireBasicAuth(event, { password: "test" });
      const auth = event.context.basicAuth!;
      expectTypeOf(auth.username).toEqualTypeOf<string>();
      expectTypeOf(auth.password).toEqualTypeOf<string | undefined>();
      expectTypeOf(auth.realm).toEqualTypeOf<string>();
    });
  });

  // The property itself stays optional: it is absent until a request authenticates.
  it("stays optional until a request is authenticated", () => {
    defineHandler((event) => {
      expectTypeOf(event.context.basicAuth).toEqualTypeOf<
        { username: string; password?: string; realm: string } | undefined
      >();
    });
  });
});

import { describe, it, expect } from "vitest";
import { build } from "esbuild";
import { fileURLToPath } from "node:url";
import zlib from "node:zlib";

const inspect = !!process.env.BUNDLE_INSPECT;

describe("benchmark", () => {
  it("bundle size (H3)", async () => {
    const code = /* js */ `
      import { H3 } from "../../src/index.ts";
      const app = new H3();
    `;
    const bundle = await getBundleSize(code);
    if (inspect) {
      return;
    }
    if (process.env.DEBUG) {
      console.log(`Bundle size (H3): ${bundle.bytes} (gzip: ${bundle.gzipSize})`);
    }
    expect(bundle.bytes).toBeLessThanOrEqual(28_400); // <28.4kb
    expect(bundle.gzipSize).toBeLessThanOrEqual(11_150); // <11.15kb
  });

  it("bundle size (H3Core)", async () => {
    const code = /* js */ `
      import { H3Core } from "../../src/index.ts";
      const app = new H3Core();
    `;
    const bundle = await getBundleSize(code);
    if (inspect) {
      return;
    }
    if (process.env.DEBUG) {
      console.log(`Bundle size (H3Core): ${bundle.bytes} (gzip: ${bundle.gzipSize})`);
    }
    expect(bundle.bytes).toBeLessThanOrEqual(9200); // <9.2kb
    expect(bundle.gzipSize).toBeLessThanOrEqual(3160); // <3.16kb
  });

  it("bundle size (defineHandler)", async () => {
    const code = /* js */ `
      import { defineHandler } from "../../src/index.ts";
      const handler = defineHandler({});
    `;
    const bundle = await getBundleSize(code);
    if (inspect) {
      return;
    }
    if (process.env.DEBUG) {
      console.log(`Bundle size (defineHandler): ${bundle.bytes} (gzip: ${bundle.gzipSize})`);
    }
    expect(bundle.bytes).toBeLessThanOrEqual(8400); // <8.4kb
    expect(bundle.gzipSize).toBeLessThanOrEqual(2870); // <2.87kb
  });
});

async function getBundleSize(code: string) {
  const res = await build({
    bundle: true,
    metafile: true,
    write: false,
    minify: inspect ? false : true,
    format: "esm",
    platform: "node",
    outfile: "index.mjs",
    treeShaking: true,
    conditions: ["browser"],
    logOverride: { "ignored-bare-import": "silent" },
    stdin: {
      contents: code,
      resolveDir: fileURLToPath(new URL(".", import.meta.url)),
      sourcefile: "index.mjs",
      loader: "js",
    },
  });

  if (inspect) {
    await process
      .getBuiltinModule("node:fs/promises")
      .writeFile("bundle.tmp.mjs", res.outputFiles[0].contents);
  }

  const { bytes } = res.metafile.outputs["index.mjs"];
  const gzipSize = zlib.gzipSync(res.outputFiles[0].text).byteLength;
  return { bytes, gzipSize };
}

